<script setup lang="ts">
const form = reactive({ name: '', description: '', password: '' })
const busy = ref(false); const error = ref('')
async function create() { busy.value = true; error.value = ''; try { const result = await $fetch('/api/groups', { method: 'POST', body: form }) as any; sessionStorage.setItem(`organizer_${result.group.id}`, result.adminToken); await navigateTo(`/g/${result.group.id}`) } catch (e: any) { error.value = e.data?.statusMessage || 'Could not create your group.' } finally { busy.value = false } }
</script>
<template><main class="home"><section class="hero"><div class="eyebrow"><span class="dot" /> FOR GROUPS, COLLECTIVES & COMMUNITIES</div><h1>Find your<br>way <em>together.</em></h1><p class="lede">Good decisions need room for every voice. Share a proposal, work through the concerns, and build a shared way forward.</p><div class="steps"><div><span>01</span><strong>Put an idea on the table.</strong><p>A proposal, a budget, a little context.</p></div><div><span>02</span><strong>Give everyone a voice.</strong><p>One link. Thoughtful responses. On your time.</p></div><div><span>03</span><strong>Keep the story.</strong><p>A living record of what you decided and why.</p></div></div><div class="note"><span>↳</span> Consensus is a conversation, not a popularity contest.</div></section><section class="panel start-panel"><div class="eyebrow">A PLACE TO BEGIN</div><h2>Your group’s next chapter.</h2><p>Create a shared home for your decisions. No account needed.</p><form @submit.prevent="create"><label>Group or organization name<input v-model="form.name" required maxlength="100" placeholder="e.g. Maple Street Collective"></label><label>A little about your group <small>optional</small><textarea v-model="form.description" maxlength="1000" rows="3" placeholder="What brings you together?" /></label><label>Group password <small>optional</small><input v-model="form.password" type="password" minlength="8" maxlength="200" autocomplete="new-password" placeholder="At least 8 characters"><span class="hint">Protects your group’s decision history. Individual decisions can have their own passwords.</span></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="button full" :disabled="busy">{{ busy ? 'Creating…' : 'Create your group →' }}</button></form><div class="panel-foot">Have a decision link? Open it directly to join in.</div></section></main></template>
